def page(records, cursor=None, limit=10):
    if limit < 1:
        raise ValueError('limit')
    ordered = sorted(records, key=lambda x: (x['timestamp'], x['id']))
    if cursor is not None:
        ordered = [x for x in ordered if (x['timestamp'], x['id']) > tuple(cursor)]
    items = ordered[:limit]
    last = items[-1] if items else None
    next_cursor = (last['timestamp'], last['id']) if len(ordered) > limit else None
    return {'items': items, 'next_cursor': next_cursor}
